#!/usr/bin/env node
// tools/assets/generate.mjs
//
// Regenerates src/assets/generated.rs from assets/manifest.json.
//
// For every manifest entry it embeds the file at `path` as a `data:` URI:
//   - kind === "item_icon"  -> ICONS
//   - every other kind      -> ARTS
//
// Missing source files: an entry that already has embedded bytes (a
// hand-seeded placeholder, or an asset generated by an earlier run) keeps
// them and is reported as a warning — a partial curator run never wipes what
// is already shipped. The run FAILS (non-zero exit) only for a declared id
// that has neither a source file nor previous embedded bytes.
//
// Run from the repository root:  node tools/assets/generate.mjs

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { extname } from "node:path";

const ROOT = process.cwd();
const MANIFEST = `${ROOT}/assets/manifest.json`;
const OUT = `${ROOT}/src/assets/generated.rs`;

const MIME = {
  ".png": "image/png",
  ".webp": "image/webp",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
};

const manifest = JSON.parse(readFileSync(MANIFEST, "utf8"));
const entries = Object.entries(manifest.assets ?? {});

/** id -> `data:` URI, parsed from the current generated.rs (previous run). */
function embeddedSoFar() {
  const map = new Map();
  if (!existsSync(OUT)) return map;
  const src = readFileSync(OUT, "utf8");
  // id → URI pairs, tolerant of the surrounding bracket/comma formatting.
  const re = /"([^"]+)",\s*"(data:[^"]*)"/g;
  let m;
  while ((m = re.exec(src)) !== null) map.set(m[1], m[2]);
  return map;
}

const previous = embeddedSoFar();

const missing = [];
const preserved = [];
const icons = [];
const arts = [];

for (const [id, entry] of entries) {
  const abs = `${ROOT}/${entry.path}`;
  if (!existsSync(abs)) {
    if (previous.has(id)) {
      preserved.push(`${id} (${entry.path})`);
      (entry.kind === "item_icon" ? icons : arts).push([id, previous.get(id)]);
      continue;
    }
    missing.push(`${id} (${entry.path})`);
    continue;
  }
  const mime = MIME[extname(entry.path).toLowerCase()] ?? "application/octet-stream";
  const uri = `data:${mime};base64,${readFileSync(abs).toString("base64")}`;
  (entry.kind === "item_icon" ? icons : arts).push([id, uri]);
}

if (missing.length > 0) {
  console.error("generate.mjs: missing source files for declared assets:");
  for (const m of missing) console.error(`  - ${m}`);
  console.error("\nPlace the files (see tools/assets/README.md) or remove the manifest entry.");
  process.exit(1);
}

if (preserved.length > 0) {
  console.warn(
    `generate.mjs: ${preserved.length} entr${preserved.length === 1 ? "y" : "ies"} have no source file yet — kept their previous embedded bytes:`,
  );
  for (const p of preserved) console.warn(`  - ${p}`);
}

const render = (name, doc, pairs) =>
  `/// ${doc}\npub const ${name}: &[(&str, &str)] = &[\n` +
  pairs.map(([id, uri]) => `    ("${id}", "${uri}"),`).join("\n") +
  `\n];\n`;

const placeholderNote =
  preserved.length === 0
    ? ""
    : `//! ${preserved.length} entr${preserved.length === 1 ? "y" : "ies"} still carry placeholder/previous bytes (source file not placed yet):\n` +
      preserved.map((p) => `//!   - ${p}\n`).join("") +
      `//!\n//! See tools/assets/README.md (curator step).\n\n`;

writeFileSync(
  OUT,
  `//! GENERATED FILE — produced by \`tools/assets/generate.mjs\`. Do not edit by hand.\n\n` +
    placeholderNote +
    render("ICONS", "Item icons (`kind: \"item_icon\"`).", icons) +
    "\n" +
    render("ARTS", "Art assets (every other `kind`).", arts),
);

console.log(`generate.mjs: wrote ${OUT} — ${icons.length} icon(s), ${arts.length} art asset(s).`);
